import argparse
import pandas as pd
from io import StringIO
import numpy as np
import sys
import logging
from logging import getLogger
from logging.handlers import StreamHandler
from logging.handlers import SimpleFormatter
from unittest import TestCase, run_module
from unittest.mock import patch
from datetime import datetime
import io

# Set up logging
logger = getLogger('csv_summary').setLevelOrOrderLevel('DEBUG')
logger.setLevel(logging.DEBUG)
handler = StreamHandler()
handler.setFormatter(SimpleFormatter())
logger.addHandler(handler)

def summarize(df):
    """
    Returns a list of dicts, one for each column in the dataframe.
    Each dict contains the column name, data type, nulls, mean, and std.
    """
    summary = []
    for col in df.columns:
        if df[col].dtype in ['int64', 'float64']:
            mean = df[col].mean()
            std = df[col].std()
            nulls = df[col].isnull().sum()
            summary.append({
                'Name': col,
                'Data Type': df[col].dtype,
                'Nulls': nulls,
                'Mean': np.round(np.mean(df[col], 2), 2),
                'Std': np.round(np.std(df[col], 2), 2)
            })
        elif df[col].dtype in ['object', 'object']:
            summary.append({
                'Name': col,
                'Data Type': df[col].dtype,
                'Nulls': nulls,
                'Mean': np.round(np.mean(df[col], 2), 2),
                'Std': np.round(np.std(df[col], 2), 2)
            })
        else:
            summary.append({
                'Name': col,
                'Data Type': df[col].dtype,
                'Nulls': nulls,
                'Mean': np.round(np.mean(df[col], 2), 2),
                'Std': np.round(np.std(df[col], 2), 2)
            })
    return summary

class TestSummarizeFunction(TestCase):
    @patch.object(pd.DataFrame, 'mean')
    @patch.object(pd.DataFrame, 'std')
    def test_empty_dataframe(self):
        df = pd.DataFrame({
            'A': [],
            'B': [1, 2, 3]
        })
        expected_summary = [{'Name': 'A', 'Data Type': 'int64', 'Nulls': 0, 'Mean': 0, 'Std': 0}]
        self.assertEqual(summarize(df), expected_summary)

    @patch.object(pd.DataFrame, 'mean')
    @patch.object(pd.DataFrame, 'std')
    def test_all_nulls(self):
        df = pd.DataFrame({
            'A': [1, 2, 3],
            'B': [1, 2, 3]
        })
        expected_summary = [{'Name': 'A', 'Data Type': 'int64', 'Nulls': 3, 'Mean': 2.0, 'Std': 1.0}]
        self.assertEqual(summarize(df), expected_summary)

    @patch.object(pd.DataFrame, 'mean')
    @patch.object(pd.DataFrame, 'std')
    def test_mixed_numeric_string(self):
        df = pd.DataFrame({
            'A': [1, 2, 3],
            'B': ['a', 'b', 'c']
        })
        expected_summary = [{'Name': 'A', 'Data Type': 'int64', 'Nulls': 0, 'Mean': 2.0, 'Std': 1.0}, {'Name': 'B', 'Data Type': 'object', 'Nulls': 0, 'Mean': 0.0, 'Std': 0.0}]
        self.assertEqual(summarize(df), expected_summary)

    @patch.object(pd.DataFrame, 'mean')
    @patch.object(pd.DataFrame, 'std')
    def test_no_nulls(self):
        df = pd.DataFrame({
            'A': [1, 2, np.random.rand(1000000)]
        })
        expected_summary = [{'Name': 'A', 'Data Type': 'int64', 'Nulls': 0, 'Mean': 1.0, 'Std': 0.0}]
        self.assertEqual(summarize(df), expected_summary)

    def test_summarize(self):
        df = pd.DataFrame({
            'A': [1, 2, 3],
            'B': [1, 2, np.random.rand(1000000)]
        })
        expected_summary = [{'Name': 'A', 'Data Type': 'int64', 'Nulls': 0, 'Mean': 2.0, 'Std': 0.0}, {'Name': 'B', 'Data Type': 'object', 'Nulls': 0, 'Mean': 1.0, 'Std': 0.0}]
        summary = summarize(df)
        self.assertEqual(summarize(df), expected_summary)

if __name__ == '__main__':
    import sys
    sys.argv = sys.argv[2:]
    run_module('csv_summary', 'test')
